frappe.listview_settings.Fees = {
    onload: function (listview) {
         listview.page.add_action_item('Create Payment Request', function () {
            var selectedFees = listview.get_checked_items();

            for (let i = 0; i < selectedFees.length; i++) {
                fees = selectedFees[i];
                if(fees.docstatus===1) {
                    createPaymentRequest(fees);
                }
            }
        });
    },
};

function createPaymentRequest(fees) {
    frappe.db.get_value('Fees', fees.name, "outstanding_amount")
    .then(r => {
        let outstanding_amount = r.message.outstanding_amount;
        if (outstanding_amount > 0){
            frappe.db.get_value('Fees', fees.name, "student")
            .then(r => {
                let student = r.message.student;
                frappe.db.get_value('Student', student, "student_email_id")
                .then(r => {
                    let student_email_id = r.message.student_email_id;
                    make_payment_request(fees.name, student, student_email_id);
                });
            });
            frappe.msgprint(__("Payment Request Created"));
        }
    });
}

 function make_payment_request(fee, student, student_email){
	if (!student_email) {
		frappe.msgprint(__("Please set the Email ID for the Student to send the Payment Request"));
	} else {
		frappe.call({
			method:"erpnext.accounts.doctype.payment_request.payment_request.make_payment_request",
			args: {
				"dt": "Fees",
				"dn": fee,
				"party_type": "Student",
				"party":student,
				"recipient_id": student_email
			},
			callback: function(r) {
			    console.log(r);
			}
		});
	}
}

