                }
            };
        });
	},

	//Auto fetch fee component from fee structure
	fee_structure: function(frm) {
		frm.set_value("fee_components" ,"");
		if (frm.doc.fee_structure) {
			frappe.call({
				method: "education.education.api.get_fee_components",
				args: {
					"fee_structure": frm.doc.fee_structure
				},
				callback: function(r) {
					if (r.message) {
						$.each(r.message, function(i, d) {
							var row = frappe.model.add_child(frm.doc, "Fee Component", "fee_components");
							row.fees_category = d.fees_category;
							row.description = d.description;
							row.amount = d.amount;
						});
					}
					refresh_field("fee_components");
				}
			});
		}
	},
});

