frappe.ui.form.on('Fees', {
    refresh: function(frm) {
        frm.add_custom_button(__('Add Discount'), function(){
        let d = new frappe.ui.Dialog({
        title: 'Add Discount',
        fields: [
            {
                label: 'Discount Name',
                fieldname: 'discount_name',
                fieldtype: 'Link',
                options: "Discount Configuration",
                get_query: function () {
    					return {
    						doctype: 'Discount Configuration',
    						filters: {
    							fee_structure: frm.doc.fee_structure,
    						},
    					};
				    }
            }
        ],
        size: 'large',
        primary_action_label: 'Submit',
        primary_action(values) {
            frappe.call({
                method: "add_discount",
                type: "POST",
                args: {
                    discount: values.discount_name,
                    fee_name: frm.doc.name
                },
                callback: function(response) {
                    console.log(response);
                }
            });
            d.hide();
            frm.doc.refresh();
        }
    });

    d.show();

    }, __("Discount"));
    frm.add_custom_button(__('Remove Discount'), function(){
        let d = new frappe.ui.Dialog({
        title: 'Add Discount',
        fields: [
            {
                label: 'Discount Name',
                fieldname: 'discount_name',
                fieldtype: 'Link',
                options: "Discount Configuration",
                get_query: function () {
    					return {
    						doctype: 'Discount Configuration',
    						filters: {
    							fee_structure: frm.doc.fee_structure,
    						},
    					};
				    }
            }
        ],
        size: 'large',
        primary_action_label: 'Submit',
        primary_action(values) {
            frappe.call({
                method: "remove_discount",
                type: "POST",
                args: {
                    discount: values.discount_name,
                    fee_name: frm.doc.name
                },
                callback: function(response) {
                    console.log(response);
                }
            });
            d.hide();
            frm.doc.refresh();
        }
    });

    d.show();
    }, __("Discount"));
  }
});

frappe.listview_settings['Fees'] = {
	add_fields: ["grand_total", "outstanding_amount", "due_date"],
	get_indicator: function(doc) {
	    frappe.call({
			method:"edu_quality.public.py.fee.get_due_date",
			args: {
			    "fee": doc.name
			},
			callback: function(r) {
			    var due_date = r.message;
			    if(flt(doc.outstanding_amount)==0) {
        			return [__("Paid"), "green", "outstanding_amount,=,0"];
        		} else if (flt(doc.outstanding_amount) > 0 && due_date >= frappe.datetime.get_today()) {
        			return [__("Unpaid"), "orange", "outstanding_amount,>,0|due_date,>,Today"];
        		} else if (flt(doc.outstanding_amount) > 0 && due_date < frappe.datetime.get_today()) {
        			return [__("Overdue"), "red", "outstanding_amount,>,0|due_date,<=,Today"];
        		}
        			}
		});
		
	}
};
